    navYalaAI: 'Yala AI',
    navGroups: 'Groups',
    yalaaiTitle: 'Meet Yala AI',
    yalaaiSubtitle: 'Ask, log, and understand your month.',
    yalaaiBullet1: 'Ask about your money in plain language and get clear answers.',
    yalaaiBullet2: 'Say "log 24 dollars for pizza" and it creates the expense for you.',
